<?php
declare(strict_types=1);
$classroom=new \ComputaKids\Classroom($db,$u);
$classes=$classroom->classes();$students=$classroom->students();$enrollments=$classroom->enrollments();
function grades(int $selected=0):void{for($i=0;$i<=9;$i++)echo '<option value="'.$i.'"'.($i===$selected?' selected':'').'>'.($i===0?'Educação Infantil':$i.'º ano').'</option>';}
function classOptions(array $classes):void{foreach($classes as $c)if(!$c['arquivada'])echo '<option value="'.h($c['id']).'">'.h($c['nome']).' — '.h($c['ano_letivo']).'</option>';}
?>
<section><h2>Painel do professor</h2><p><?=count($classes)?> turmas · <?=count($students)?> alunos</p></section>
<section><h2>Nova turma</h2><form method="post"><?php token();?><label>Nome<input name="name" maxlength="120" required></label><label>Etapa<select name="grade"><?php grades();?></select></label><label>Ano letivo<input name="year" type="number" min="2000" max="2100" value="<?=date('Y')?>" required></label><button name="action" value="class_save">Cadastrar turma</button></form></section>
<section><h2>Minhas turmas</h2><?php foreach($classes as $c):?><details><summary><?=h($c['nome'])?> · <?=h($c['ano_letivo'])?> · <?=$c['arquivada']?'Arquivada':'Ativa'?></summary><form method="post"><?php token();?><input type="hidden" name="id" value="<?=h($c['id'])?>"><label>Nome<input name="name" value="<?=h($c['nome'])?>" required maxlength="120"></label><label>Etapa<select name="grade"><?php grades((int)$c['etapa']);?></select></label><label>Ano letivo<input name="year" type="number" value="<?=h($c['ano_letivo'])?>" required></label><button name="action" value="class_save">Salvar</button> <button name="action" value="<?=$c['arquivada']?'class_restore':'class_archive'?>" formnovalidate><?=$c['arquivada']?'Reativar':'Arquivar'?></button></form></details><?php endforeach;?></section>
<section><h2>Novo aluno</h2><form method="post"><?php token();?><label>Nome<input name="name" required maxlength="180"></label><label>Usuário<input name="login" required maxlength="100"></label><label>Senha inicial<input name="password" type="password" minlength="12" required></label><label>Turma<select name="class" required><option value="">Selecione</option><?php classOptions($classes);?></select></label><button name="action" value="student_create">Cadastrar aluno</button></form></section>
<section><h2>Meus alunos</h2><div class="scroll"><table><thead><tr><th>Nome</th><th>Usuário</th><th>Situação</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><?=h($s['nome'])?></td><td><?=h($s['login'])?></td><td><?=$s['ativo']?'Ativo':'Inativo'?></td></tr><?php endforeach;?></tbody></table></div></section>
<section><h2>Matrículas</h2><form method="post"><?php token();?><label>Aluno<select name="student" required><option value="">Selecione</option><?php foreach($students as $s):?><option value="<?=h($s['id'])?>"><?=h($s['nome'])?></option><?php endforeach;?></select></label><label>Turma<select name="class" required><option value="">Selecione</option><?php classOptions($classes);?></select></label><button name="action" value="enroll">Matricular</button></form><div class="scroll"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Ação</th></tr></thead><tbody><?php foreach($enrollments as $m):?><tr><td><?=h($m['aluno'])?></td><td><?=h($m['turma'])?></td><td><form method="post"><?php token();?><input type="hidden" name="student" value="<?=h($m['aluno_id'])?>"><input type="hidden" name="class" value="<?=h($m['turma_id'])?>"><button name="action" value="unenroll">Desvincular</button></form></td></tr><?php endforeach;?></tbody></table></div></section>

<section><h2>Métodos de acesso dos alunos</h2><p>Escolha os métodos permitidos por turma. Os acessos compartilhado e remoto ainda estão em desenvolvimento; não desative o individual antes da homologação.</p>
<?php foreach((new \ComputaKids\AccessPolicy($db,$u))->all() as $p):?>
<details><summary><?=h($p['nome'])?> — <?=h($p['ano_letivo'])?></summary>
<form method="post"><?php token();?><input type="hidden" name="id" value="<?=h($p['id'])?>">
<label><input style="display:inline;width:auto" type="checkbox" name="individual" <?=$p['individual']?'checked':''?>> Login individual</label>
<label><input style="display:inline;width:auto" type="checkbox" name="shared" <?=$p['compartilhado']?'checked':''?>> Senha padrão</label>
<label><input style="display:inline;width:auto" type="checkbox" name="remote" <?=$p['remoto']?'checked':''?>> Autorização remota</label>
<label>Nova senha padrão (deixe vazio para manter)<input name="shared_password" type="password" minlength="12" autocomplete="new-password"></label>
<button name="action" value="access_save">Salvar configuração</button></form></details><?php endforeach;?></section>
<section><h2>Autorizar computador</h2><form method="post"><?php token();?><button type="button" id="scan-start">Escanear QR Code</button><button type="button" id="scan-stop" hidden>Parar câmera</button><video id="scan-video" playsinline muted hidden style="max-width:100%"></video><p id="scan-status" role="status"></p><label>Código do computador<input id="remote-code" name="code" required pattern="[A-Fa-f0-9]{16}" maxlength="16"></label><label>Matrícula<select id="remote-enrollment" required><option value="">Selecione turma e aluno</option><?php foreach($enrollments as $m):?><option value="<?=h($m['turma_id'])?>:<?=h($m['aluno_id'])?>"><?=h($m['turma'])?> — <?=h($m['aluno'])?></option><?php endforeach;?></select></label><input type="hidden" name="class" id="remote-class"><input type="hidden" name="student" id="remote-student"><button name="action" value="remote_authorize">Autorizar</button></form><script>document.getElementById('remote-enrollment').addEventListener('change',e=>{const [c,s]=e.target.value.split(':');document.getElementById('remote-class').value=c||'';document.getElementById('remote-student').value=s||'';});</script></section><script src="assets/jsQR.js"></script><script src="assets/scan.js"></script>